// Loads the character-library cut-outs (src/art/toon/library-data.js, generated by tools/extract-toon-characters.mjs).
// loadLibrary() -> Promise<{ colby_front, colby_side, pete_front, pete_side }> each { w, h, img } where img is a drawable
// (canvas in the browser, decoded RGBA object in Node). Cached.
import { DATA, DIMS } from './library-data.js';
import { toDrawable } from '../../kits/library-sprites/index.js';

let cache = null;
export function loadLibrary() {
  if (!cache) cache = (async () => {
    const out = {};
    for (const k of Object.keys(DATA)) out[k] = { w: DIMS[k].w, h: DIMS[k].h, img: await toDrawable(DATA[k]) };
    return out;
  })();
  return cache;
}
export const LIBRARY_SPRITES = Object.freeze(Object.keys(DIMS));
